{
  "name": "@smthrs/bug-worker",
  "version": "0.0.1",
  "private": true,
  "description": "Cloudflare Worker behind bug.smithers.sh that receives smithers bug reports and stores them in KV",
  "type": "module",
  "scripts": {
    "test": "bun test tests",
    "typecheck": "vibelang -p tsconfig.json --noEmit",
    "plan": "alchemy deploy --dry-run --stage prod",
    "deploy": "node ../../.smithers/flows/rollout/refuse-unqualified.mjs",
    "destroy": "alchemy destroy --stage prod"
  },
  "dependencies": {
    "zod": "4.6.7"
  },
  "devDependencies": {
    "@smthrs/control": "workspace:*",
    "@types/node": "26.4.1",
    "alchemy": "2.0.0-beta.82",
    "bun-types": "^1.4.0",
    "effect": "4.0.5",
    "typescript": "~5.9.3",
    "vibelang": "0.0.8"
  }
}

{
  "compilerOptions": {
    // DOM as well as ESNext: the contract test reaches @smthrs/control, whose
    // WebCrypto sources are typed against DOM, as the module that owns them
    // declares.
    "lib": ["ESNext", "DOM"],
    "target": "ESNext",
    "module": "ESNext",
    "moduleDetection": "force",
    "moduleResolution": "bundler",
    "allowImportingTsExtensions": true,
    "allowJs": true,
    "verbatimModuleSyntax": true,
    "noEmit": true,
    "strict": true,
    "skipLibCheck": true,
    "types": ["bun-types"]
  },
  "include": ["src/**/*", "tests/**/*", "alchemy.run.ts"]
}
